content.content:
=== ClaimStatus

/**
 * Where a claim is in its life: it starts DRAFT, is opened and then settled; a clerk settling one whose due is above
 * the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT,
 * OPEN or PENDING claim can be voided, and a steward may void a SETTLED one within 7 days of its settlement. Only a
 * DRAFT can be edited. VOID is final. A DRAFT can be deleted (DELETED), and restored to a DRAFT on the sheet's today it
 * was deleted; a DELETED claim counts nowhere. Only OPEN, PENDING and SETTLED claims count toward the totals.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED;

    /** Whether a claim with this status is open: OPEN, or PENDING (handled like an open claim). */
    public boolean open() {
        return this == OPEN || this == PENDING;
    }
}
=== Rounding


/**
 * How a claim's live figures (the rate step and the late charge) are rounded: a claim dated before the sheet's
 * policy date rounds half up, one dated on or after it half to even. A correction rounds by the date of the claim it
 * corrects, not its own; {@code dates} holds the claims' dates by number.
 */
public record Rounding(LocalDate policyDate, Map<String, LocalDate> dates) {

    /** The rounding by the policy date for the given claims (those a correction may name). */
    public static Rounding of(LocalDate policyDate, List<Claim> claims) {
        Map<String, LocalDate> dates = new HashMap<>();
        for (Claim claim : claims) {
            if (claim.number() != null) {
                dates.put(claim.number(), claim.date());
            }
        }
        return new Rounding(policyDate, dates);
    }

    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
    public LocalDate dateOf(Claim claim) {
        return claim.correction() ? dates.getOrDefault(claim.corrects(), claim.date()) : claim.date();
    }

    /** How the claim's live figures round. */
    public RoundingMode modeFor(Claim claim) {
        return dateOf(claim).isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
=== LateCharge


/**
 * What an overdue claim is charged: for every full 30 days it is overdue (its due-by, fixed when it was created, plus
 * the grace days of its person's grade in force on its date, before the sheet's today), the late percent in force on
 * that boundary date (the due-by plus the grace plus 30, 60, 90 ... days) of its figure plus the charges of the
 * boundaries before it (compounding), rounded like the claim's due, the charges added up; a boundary whose percent is 0.00 adds nothing. Never bound by a
 * statement: it follows the sheet's today until the claim is settled. A correction, and a deferred claim, is never charged.
 */
public record LateCharge(Function<LocalDate, BigDecimal> pctOn, Function<Claim, Integer> graceOf, LocalDate today) {

    /** A charge with no grace days for any claim. */
    public LateCharge(Function<LocalDate, BigDecimal> pctOn, LocalDate today) {
        this(pctOn, (claim) -> 0, today);
    }

    /** The days in each period an overdue claim is charged for. */
    public static final int PERIOD_DAYS = 30;

    /** The charge on the claim's figure (null: n/a, charged nothing); zero unless the claim is overdue. */
    public BigDecimal on(Claim claim, BigDecimal figure, RoundingMode mode) {
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        if (figure == null || !claim.status().open() || claim.deferred(today) || claim.correction()) {
            return charge;
        }
        LocalDate lateFrom = claim.dueBy().plusDays(graceOf.apply(claim));
        long late = ChronoUnit.DAYS.between(lateFrom, today);
        long periods = late > 0 ? late / PERIOD_DAYS : 0;
        for (long period = 1; period <= periods; period++) {
            BigDecimal pct = pctOn.apply(lateFrom.plusDays(period * PERIOD_DAYS));
            if (pct.signum() != 0) {
                charge = charge.add(Claim.due(figure.add(charge), pct, mode));
            }
        }
        return charge;
    }
}
