import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { useClaims } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { gradeOn } from '../people/people';
import type { GradeFrom } from '../people/people';

/** A role given to a user name: clerk, steward or viewer (sees everything, changes nothing). A name with none given is a clerk. */
export type UserRole = { user: string; role: string };

/**
 * The sheet's settings as the store holds them: the clerk limit (two decimals; null: no limit), above
 * which a clerk cannot settle a claim, the floor (two decimals), below which no live due goes, the terms
 * (whole days) a claim is due by after its date, the terms set
 * for each grade that has its own (by grade; any other grade uses the sheet's terms), the late percent (two decimals) an overdue claim
 * gains of its figure every full 30 days, the rounding policy date (yyyy-MM-dd; '': blank, the
 * sheet's today), the period numbering from date (yyyy-MM-dd; '': off — on or after it, an opened claim is
 * numbered within its period), the entry date (yyyy-MM-dd; '': off — a new claim left without a date takes it instead of the
 * sheet's today), the cap (two decimals; '': none — a person's due-total is at most it), the proof threshold (two decimals; '': none — a
 * claim whose due is above the one in force on its date is settled or approved only once it has a proof), the note threshold (two decimals; '': none — a
 * claim whose due is above the one in force on its date is opened only with a note), and the roles
 * given to user names. The clerk limit, floor, terms, grade terms, late percent, cap, proof threshold and note threshold are those in force on the sheet's
 * today; `history` holds every value recorded for them, by key (floor, late-pct, terms, terms-<grade>, grace-<grade>, clerk-limit,
 * cap, proof-threshold, proof-threshold-<grade>, note-threshold), oldest from-date first (value '': blank). `permissions` is the permission matrix: by action, the
 * roles allowed it, comma separated ('': blank, the standing rule); it is not dated.
 * `graceDays` is the grace days (whole days; '': off — when the sheet's today is changed, an open period whose
 * to-date plus them is before the new today is closed); it is not dated.
 * `delegations` is the steward role delegated to user names, in the order made.
 * `alertThreshold` is the alert threshold ('': off); it is not dated.
 * `pot` is the pot ('': none), the pot of each pool that is a member of no pool, shared out among its members when it is balanced; it is not dated.
 * `parent` is the parent sheet's id ('': none), whose rates a grade with none of its own in force takes; it is not dated.
 * `fiscalStartMonth` is the month (1 to 12) each fiscal year starts in; it is not dated.
 */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; gradeTerms: Record<string, number>; latePct: string; policyDate: string; periodNumberingFrom: string; entryDate: string; cap: string; proofThreshold: string; noteThreshold: string; roles: UserRole[]; history: Record<string, FromValue[]>; permissions: Record<string, string>; graceDays: string; delegations: Delegation[]; pot: string; parent: string; fiscalStartMonth: string; alertThreshold: string };

/**
 * The steward role delegated by a steward (`by`) to a user name, from a from-date to a to-date (yyyy-MM-dd), both
 * inclusive: while the sheet's today is inside them the user acts as a steward.
 */
export type Delegation = { user: string; from: string; to: string; by: string };

/** A dated setting's value recorded from a date (yyyy-MM-dd); '': blank. */
export type FromValue = { from: string; value: string };

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it, else `start`. */
export function valueOn(history: FromValue[] | undefined, date: string, start: string): string {
  let found = start;
  for (const v of history ?? []) {
    if (v.from <= date) found = v.value === '' ? start : v.value;
  }
  return found;
}

/** The floor a sheet starts with: a claim's live due is at least it. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days: a claim is due by its date plus them. */
export const DEFAULT_TERMS = 14;

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The roles a user name can be given. */
export const ROLES = ['clerk', 'steward', 'viewer'];

/** The actions the permission matrix covers. */
export const PERMISSION_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'];

/** The roles allowed an action when its permission entry is blank. */
export const STANDING_PERMISSIONS: Record<string, string> = {
  open: 'clerk,steward',
  settle: 'clerk,steward',
  void: 'clerk,steward',
  reassign: 'steward',
  close: 'clerk,steward',
  reopen: 'steward',
};

/** Roles as a permission entry takes them: clerk or steward, comma separated. */
export const ROLE_LIST = /^\s*(clerk|steward)\s*(,\s*(clerk|steward)\s*)*$/i;

/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d{1,13}(\.\d{1,2})?|\.\d{1,2})$/;

/** A percent: 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** 0 or more whole days. */
export const DAYS = /^\d{1,5}$/;

/** The query key for the sheet's settings; under sheetKey, so re-loading the sheet re-reads them. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;

/** The sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: !!sheet,
  });
}

/**
 * The grace days of the grade of a claim's person in force on its date, in force on that date (0: none): the claim is
 * overdue only once its due-by plus them is before the sheet's today.
 */
export function claimGrace(claim: { date: string }, grades: GradeFrom[], rules: DueRules): number {
  return rules.graceOn(gradeOn(grades, claim.date), claim.date);
}

/** The sheet's floor (two decimals): a claim's live due is at least it. */
export function useFloor(): string {
  return useSettings().data?.floor ?? DEFAULT_FLOOR;
}


/** A date as the settings form takes it: yyyy-MM-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * What a claim's due is worked out from: the floor and late percent in force on a claim's date, the grace days of a grade
 * in force on a date (0: none), the sheet's today, its policy
 * date in force (blank: today), its cap in force on today ('': none) and the dates of its claims by number (a correction rounds by the date
 * of the claim it corrects).
 */
export type DueRules = {
  floorOn: (date: string) => string;
  latePctOn: (date: string) => string;
  graceOn: (grade: string | undefined, date: string) => number;
  today: string;
  policyDate: string;
  cap: string;
  claimDates: Map<string, string>;
};

/** The sheet's rules for working out a claim's due. */
export function useDueRules(): DueRules {
  const settings = useSettings().data;
  const today = useSheetToday();
  const claims = useClaims().data;
  return useMemo(() => dueRules(settings, today, claims ?? []), [settings, today, claims]);
}

/** A sheet's rules for working out a claim's due, from its settings, its today and its claims. */
export function dueRules(settings: Settings | undefined, today: string, claims: Claim[]): DueRules {
  const history = settings?.history;
  return {
    floorOn: (date: string) => valueOn(history?.floor, date, DEFAULT_FLOOR),
    latePctOn: (date: string) => valueOn(history?.['late-pct'], date, DEFAULT_LATE_PCT),
    graceOn: (grade: string | undefined, date: string) => (grade ? Number(valueOn(history?.[`grace-${grade}`], date, '0')) : 0),
    today,
    policyDate: settings?.policyDate || today,
    cap: settings?.cap ?? '',
    claimDates: new Map(claims.filter((c) => c.number !== null).map((c) => [c.number!, c.date])),
  };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asNumber, useSearchParam } from '../../url/useSearchParam';
import { sheetKey, useCurrentSheet } from '../session/session';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade recorded for a person, in force from its from-date (yyyy-MM-dd; null: from the beginning of time). */
export type GradeFrom = { grade: string; from: string | null };

/** The grade in force on the date (yyyy-MM-dd): the one recorded with the latest from-date on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): string | undefined {
  let found: GradeFrom | undefined;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (!found || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** A hold on a person, from its from-date to its to-date, both inclusive (yyyy-MM-dd; null: open-ended). */
export type Hold = { from: string | null; to: string | null };

/** Whether a hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to);

/**
 * The holds that apply to a person's live totals on the sheet's `today`: their own, and — from the day their
 * retirement date is reached — one covering every date, so their open and pending claims leave the totals as a
 * hold's would (settled ones, and ones a statement binds, still count).
 */
export const liveHolds = (p: { holds: Hold[]; retiredFrom: string | null }, today: string): Hold[] =>
  p.retiredFrom !== null && today !== '' && today >= p.retiredFrom ? [...p.holds, { from: null, to: null }] : p.holds;

/**
 * A person on the sheet as the store holds them; `grade` is the one in force on the sheet's today and
 * `grades` every grade recorded for them, each from its from-date; `version` counts their saves. `statementCount` counts
 * the statements taken of them; `statedTotal` is the last one's due-total and `statementDate` the
 * sheet's today when it was taken, both null before the first. `retired` is whether a retirement date is
 * set (whatever the date), `retiredFrom` that date, null while they are not retired. `held` is whether
 * they have any hold, `holds` each hold, oldest first: their open claims dated within one, and not bound by a
 * statement, count in no live total. `terms` is the person's own terms in days, null when they have none;
 * `contact` their contact (trimmed, lower-cased), null when they have none. `clashing` is whether another sheet of
 * the sheet's tree (its ancestors and descendants) uses their name or any of their aliases as a name or alias.
 * `origin` is the sheet they were transferred from, null when they were not transferred here. `pastRetirements` are
 * the retirements they were unretired from, oldest first: a claim dated after one's from and before its to is refused.
 * `tags` are their tags, sorted (none: empty).
 */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  terms: number | null;
  contact: string | null;
  clashing: boolean;
  origin: string | null;
  pastRetirements: { from: string; to: string }[];
  tags: string[];
};

/**
 * The fields the person form submits; a blank `gradeFrom` is the sheet's today, blank `terms` none of their own,
 * blank `contact` none, `tags` comma separated (blank: none).
 */
export type PersonInput = { name: string; grade: string; gradeFrom: string; terms: string; contact: string; tags: string };

/** The query key for the sheet's people; under sheetKey, so re-loading the sheet re-reads them. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

/** The sheet's people, in their order in the list (new people go to the end; they can be moved up and down). */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open in the person form, if any. */
export const useEditingPerson = () => useSearchParam('person', asNumber);

/** Whether retired people are listed; off until the toggle is turned on, and kept when a sheet is loaded. */
export const useShowRetired = () => useSearchParam('retired', asFlag);

/** The keys the people list can be sorted on. */
export const SORT_KEYS = ['added', 'name', 'grade', 'due-total'] as const;
export type SortKey = (typeof SORT_KEYS)[number];

/** How this screen sorts the people list; added (their order in the list) until another key is chosen. */
