392	            throw new InvalidClaimException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be split.");
393	        }
394	        if (!settings.find(claim.sheetId()).may(user, "open")) {
395	            throw new InvalidClaimException("The user's role is not allowed to open a claim, so cannot split one.");
396	        }
