=== person/TransferPerson
/**
 * Transfers the person to the other sheet: they arrive as its newest person with their grades, terms, contact and
 * aliases and statements (holds, patron links, pool memberships and watches dropped), and their claims arrive in the
 * order they were added, keeping status, dates, notes, frozen figures, any figure a statement bound, tags and logs,
 * losing their references. Each claim that had a number takes the other sheet's next one, in the order the claims
 * were opened; a correction or split that named one of them by number names its new number. They leave this sheet.
 * When they are merged on arrival, they are then merged into that person exactly as {@link MergePerson} does.
 */
public class TransferPerson {
    public void transfer(@Val Transfer transfer, PersonRepository people, ClaimRepository claims,
            SheetRepository sheets, SettingRepository settings, PeriodRepository periods, Out<Transferred> arrived) {
        Person person = transfer.person();
        String to = transfer.to();
        // a person merged on arrival first arrives under a name no one there has, as theirs may be taken
        long personId = transfer.into() == null ? people.transfer(person, to)
                : people.transfer(person, to, "\u0000transfer " + person.sheetId() + " " + person.id());
        List<ClaimRepository.Moved> moved = claims.transfer(person.sheetId(), person.id(), to, personId);
        Map<String, String> numbers = new HashMap<>();
        for (ClaimRepository.Moved m : moved.stream().filter((m) -> m.number() != null)
                .sorted(Comparator.comparing(ClaimRepository.Moved::opened)
                        .thenComparing(ClaimRepository.Moved::id))
                .toList()) {
            Claim claim = claims.find(to, m.id());
            numbers.put(m.number(), ClaimNumbers.next(claim, sheets, settings, periods));
        }
        claims.renumberTransferred(to, moved, numbers);
        people.dropTransferred(person);
        if (transfer.into() == null) {
            arrived.set(new Transferred(people.find(to, personId), null));
            return;
        }
        Merge merge = new Merge(people.find(to, personId).withName(person.name()), transfer.into());
        new MergePerson().merge(merge, claims, people);
        arrived.set(new Transferred(people.find(to, transfer.into().id()), merge));
    }
}
=== person/CheckTransfer
/**
 * Refuses (400) a transfer unless a steward transfers a person who is not retired to another sheet, not archived,
 * where no one on any other sheet of its tree (but their own entries) has their name or any of their aliases as a name
 * or alias. When someone on the other sheet has their name or one of their aliases as a name or alias, the person is
 * merged into them on arrival, refused when that is more than one person or they are retired; otherwise no one there
 * may have their contact. Publishes the transfer.
 */
public class CheckTransfer {
    public void check(@RequestParam("user") String user, @Val Person person, @Val TransferRequest request,
            SettingRepository settings, SheetRepository sheets, PersonRepository people, NameTree tree,
            Out<Transfer> transfer)
            throws InvalidPersonException {
        if (settings.find(person.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidPersonException("Only a steward may transfer people.");
        }
        String to = request.to();
        if (to.equals(person.sheetId())) {
            throw new InvalidPersonException("A person cannot be transferred to their own sheet.");
        }
        if (person.retired()) {
            throw new InvalidPersonException("A retired person cannot be transferred.");
        }
        if (sheets.isArchived(to)) {
            throw new InvalidPersonException("An archived sheet cannot be changed.");
        }
        List<String> names = new ArrayList<>();
        names.add(person.name());
        names.addAll(people.aliases(person.sheetId(), person.id()));
        Set<String> treeTaken = tree.taken(to, person.id());
        Person into = null;
        for (String name : names) {
            if (NameTree.clashing(treeTaken, name, List.of())) {
                throw new InvalidPersonException("A sheet related to the other sheet already has " + name + ".");
            }
            Person found = people.findByName(to, name);
            if (found != null) {
                if (into != null && !into.id().equals(found.id())) {
                    throw new InvalidPersonException("More than one person on the other sheet has their names.");
                }
                into = found;
            }
        }
        if (into != null && into.retired()) {
            throw new InvalidPersonException("A retired person cannot be merged.");
        }
        if (into == null && person.contact() != null && people.contactTaken(to, person.contact(), null)) {
            throw new InvalidPersonException("The other sheet already has that contact.");
        }
        transfer.set(new Transfer(person, to, into));
    }
}
=== person/MergePerson
/**
 * Merges the person into the other: their claims move to the other (numbers and dates kept), listed after the
 * other's in the order they were added, each keeping any figure a statement bound; then their name, aliases, patrons,
 * pool memberships and statements pass to the other (see {@link PersonRepository#merge}) and they leave the sheet.
 */
public class MergePerson {
    public void merge(@Val Merge merge, ClaimRepository claims, PersonRepository people) {
        List<Claim> moving = new ArrayList<>(claims.findForPerson(merge.from().sheetId(), merge.from().id()));
        Collections.reverse(moving);
        for (Claim claim : moving) {
            claims.moveMerged(claim, merge.into().id());
        }
        people.merge(merge.from(), merge.into());
    }
}
