/**
 * Saves each imported person, in order, as the person form does: a new one added and recorded as PERSON_ADDED, an
 * existing one updated and recorded as PERSON_EDITED, each followed by the rollup lines that save moved.
 */
public class SaveImportedPeople {
    public void save(@Val ImportedPersons imported, @RequestParam("user") String user, PersonRepository repository,
            RollupService rollups, Audit audit, Out<ImportResult> result) throws StalePersonException {
        int added = 0;
        int updated = 0;
        for (ImportedPersons.Entry entry : imported.people()) {
            Person person = entry.person();
            Rollup before = rollups.compute(person.sheetId());
            Person stored = repository.save(person);
            if (entry.update()) {
                if (stored == null) {
                    throw new StalePersonException(person.name());
                }
                new AuditPersonEdited().audit(stored, entry.termsChange(), user, audit);
                updated++;
            } else {
                new AuditPersonAdded().audit(stored, user, audit);
                added++;
            }
            RollupLines.record(before, rollups.compute(person.sheetId()), person.sheetId(), user, audit);
        }
        result.set(new ImportResult(added, updated));
    }
}
=== importpeople/CheckImportedPeopleUnique
/**
 * Builds each imported person and checks them with the person form's rules against the sheet and its tree (names,
 * aliases, contacts). A line whose name is a person's name or alias on the sheet updates that person as the form's
 * edit does (grade from the sheet's today; terms and contact only when the line gives them); any other line adds a
 * person as the form's add does. Two lines for the same person, or any line refused, refuse the whole import, before
 * anything is written.
 */
public class CheckImportedPeopleUnique {
    public void check(@Val ImportedPeople imported, @Val Sheet sheet, PersonRepository repository, NameTree tree,
            SheetRepository sheets, Out<ImportedPersons> built) throws InvalidPersonException {
        List<ImportedPersons.Entry> people = new ArrayList<>();
        Set<Long> updating = new HashSet<>();
        int number = 0;
        for (PersonRequest request : imported.people()) {
            number++;
            try {
                Person existing = repository.findByName(sheet.id(), request.name());
                if (existing == null) {
                    Person[] person = new Person[1];
                    new BuildPerson().build(request, sheet, value -> person[0] = value);
                    new CheckPersonNameUnique().check(person[0], repository, tree);
                    people.add(new ImportedPersons.Entry(person[0], null));
                    continue;
                }
                if (!updating.add(existing.id())) {
                    throw new InvalidPersonException("The person " + existing.name()
                            + " is already given by an earlier line.");
                }
                PersonRequest edit = new PersonRequest(existing.name(), request.grade(), "", null,
                        request.termsDays() != null ? request.terms()
                                : existing.terms() == null ? "" : String.valueOf(existing.terms()),
                        request.contactOrNull() != null ? request.contact()
                                : existing.contact() == null ? "" : existing.contact(), null);
                Person[] person = new Person[1];
                PersonTermsChange[] change = new PersonTermsChange[1];
                try {
                    new ApplyPerson().apply(edit, existing, sheets, value -> person[0] = value,
                            value -> change[0] = value);
                } catch (StalePersonException e) {
                    throw new InvalidPersonException(e.getMessage());
                }
                new CheckPersonNameUnique().check(person[0], repository, tree);
                people.add(new ImportedPersons.Entry(person[0], change[0]));
            } catch (InvalidPersonException e) {
                throw new InvalidPersonException("Person " + number + ": " + e.getMessage());
            }
        }
        built.set(new ImportedPersons(people));
    }
}
=== importpeople/ValidateImportPeopleRequest
/**
 * Splits the text into lines of name,grade,terms,contact (terms and contact may be absent or blank; blank lines are
 * skipped) and checks each with exactly the person form's rules. Nothing pasted is refused, as is a line with more
 * than four fields, and a name (ignoring case) or contact an earlier line gave.
 */
public class ValidateImportPeopleRequest {
    public void validate(@RequestBody @Valid ImportPeopleRequest request, Out<ImportedPeople> imported)
            throws InvalidPersonException {
        String text = request.text() == null ? "" : request.text();
        List<PersonRequest> people = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        int number = 0;
        for (String line : text.split("\\r?\\n")) {
            number++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", -1);
            if (fields.length > 4) {
                throw new InvalidPersonException("Line " + number + ": too many fields.");
            }
            String name = fields[0];
            String grade = fields.length > 1 ? fields[1] : "";
            String terms = fields.length > 2 ? fields[2] : "";
            String contact = fields.length > 3 ? fields[3] : "";
            // The person form's field limits, which its request checks on binding.
            if (name.length() > 200 || grade.length() > 10 || terms.length() > 30 || contact.length() > 200) {
                throw new InvalidPersonException("Line " + number + ": a field is too long.");
            }
            PersonRequest[] person = new PersonRequest[1];
            try {
                new ValidatePersonRequest().validate(new PersonRequest(name, grade, "", null, terms, contact, null),
                        value -> person[0] = value);
            } catch (InvalidPersonException e) {
                throw new InvalidPersonException("Line " + number + ": " + e.getMessage());
            }
            if (!names.add(person[0].name().toLowerCase(Locale.ROOT))) {
                throw new InvalidPersonException("Line " + number + ": the name " + person[0].name()
                        + " is already given by an earlier line.");
            }
            if (person[0].contactOrNull() != null && !contacts.add(person[0].contact())) {
                throw new InvalidPersonException("Line " + number + ": the contact " + person[0].contact()
                        + " is already given by an earlier line.");
            }
            people.add(person[0]);
        }
        if (people.isEmpty()) {
            throw new InvalidPersonException("Paste at least one line of name,grade,terms,contact.");
        }
        imported.set(new ImportedPeople(people));
    }
}
